      "code": "def build(p):\n    # Hexagonal grip; z=0 is the nut insertion face and print bed.\n    body = cq.Workplane('XY').polygon(6, p.knob_d).extrude(p.knob_h)\n\n    # Nut cavity starts behind the flexible retaining lip.\n    af = p.nut_af + p.pocket_clearance\n    hex_d = af / 0.8660254037844386\n    pocket = (cq.Workplane('XY').workplane(offset=p.lip_t)\n              .polygon(6, hex_d).extrude(p.pocket_floor_z - p.lip_t))\n    body = body.cut(pocket)\n\n    # Small entry aperture through the lip and a continuous M3 bolt bore\n    # from the pocket floor through the opposite face.\n    entry = cq.Workplane('XY').circle(p.entry_d / 2).extrude(p.lip_t)\n    bore = (cq.Workplane('XY').workplane(offset=p.pocket_floor_z - 0.05)\n            .circle(p.screw_clearance_d / 2)\n            .extrude(p.knob_h - p.pocket_floor_z + 0.1))\n    body = body.cut(entry).cut(bore)\n\n    # Six radial relief cuts split the entry lip into compliant fingers.\n    # Slots align with the nut's hex corners and extend beyond the nut corners.\n    slot_len = p.slot_outer_r - p.entry_d / 2\n    for i in range(6):\n        slot = (cq.Workplane('XY')\n                .box(slot_len, p.slot_width, p.lip_t + 0.15,\n                     centered=(False, True, False))\n                .translate((p.entry_d / 2, 0, 0))\n                .rotate((0, 0, 0), (0, 0, 1), i * 60))\n        body = body.cut(slot)\n    return body",
